inline void stageFight(G2NaturalDriver& r,const std::string& id,bool adaptive=false){
 auto& g=r.game;const auto& d=g.content().enemies.at(id);if(isDifficultyPreset(g.content(),g.session(),d.deadFlag)&&g.session().flag(d.deadFlag)){return;}need(g.mapId()==d.map&&(!d.rules.contains("activation_fact")||g.session().flag(d.rules.at("activation_fact"))),"08 natural target inactive");const int threshold=d.rules.value("behavior",std::string{})=="chimera"?250:d.rules.value("death_damage_threshold",100);int fired=0,wait=0,readyTick=0;const auto target=findCharacter(g.world(),id).motion.tile();bool reachable=false;for(auto side:{Direction::Down,Direction::Up,Direction::Right,Direction::Left}){const auto adjacent=adjacentTile(target,side);reachable|=g.world().player().motion.tile()==adjacent||next(g.world(),adjacent).has_value();}need(reachable,"08 target lies in another source partition: "+id);
 for(int n=0;n<2200&&!g.session().flag(d.deadFlag);++n){auto& s=g.session();need(s.hp()>0&&g.mode()==ApplicationMode::Playing,"08 natural battle failed");InputFrame in;const int weapon=s.equipped(1),rounds=s.magazine(weapon);int damage=0;for(const auto& enemy:g.enemyStates()){if(enemy.id==id){damage=enemy.damage;}}
  if(g.foreground()!=ForegroundKind::None||g.dialogue().active()){if(n%8==0){in=key();}}
  else if(s.flag(10)||s.flag(45)||!s.flag(1)){if(n%2==0){in=key(n%4==0?InputAction::Up:InputAction::Left);}}
  else if(adaptive&&s.hp()<65&&r.healingItem()){r.lowerForMenu(readyTick);r.healTo(100);continue;}
  else if(damage>=threshold){}
  else if(!g.raised()){in=key(InputAction::Weapon);}
  else{const auto p=g.world().player().motion.tile(),t=findCharacter(g.world(),id).motion.tile();const int dx=t.x-p.x,dy=t.y-p.y;const auto face=std::abs(dx)>std::abs(dy)?(dx>0?Direction::Right:Direction::Left):(dy>0?Direction::Down:Direction::Up);
   if((dx&&dy)||std::abs(dx)+std::abs(dy)>4){for(auto side:{Direction::Down,Direction::Up,Direction::Right,Direction::Left}){if(auto step=next(g.world(),adjacentTile(t,side))){in.movement=step;break;}}}
   else if(g.world().player().motion.facing()!=face){in.buttons[int(InputAction::Weapon)].held=true;in.movement=face;}
   else if(wait==0){if(rounds==0&&!s.hasReserve()){if(adaptive){r.lowerForMenu(readyTick);r.equipAvailable({21,15,17,19,13});}else{r.lower();r.equip(21);}need(s.magazine(s.equipped(1))>0||s.hasReserve(),"08 actual second weapon exhausted");continue;}in=key(InputAction::Attack);wait=36;}
  }
  if(wait>0){--wait;}r.tick(in);const int used=std::max(0,rounds-s.magazine(weapon));fired+=used;if(adaptive&&used>0){readyTick=r.ticks+r.fireRecoveryTicks(weapon);}if(n%200==0){const auto p=g.world().player().motion.tile(),t=findCharacter(g.world(),id).motion.tile();std::cout<<"08 fight "<<id<<" n="<<n<<" p="<<p.x<<","<<p.y<<" e="<<t.x<<","<<t.y<<" dmg="<<damage<<" hp="<<s.hp()<<" mag="<<s.magazine(weapon)<<" corr="<<s.conditions().corroded<<'\n';}
 }
 need(g.session().flag(d.deadFlag)&&fired>0,"08 natural battle stalled before source death");r.lower();if(g.session().hp()<80&&g.session().count(5)>0){r.item(5);}std::cout<<"08 real kill "<<id<<" shots="<<fired<<" HP="<<g.session().hp()<<'\n';
}

